      guardHome(spec, m => /metformin|glipizide|glyburide|glimepiride|sglt2|empagliflozin|dapagliflozin|canagliflozin/i.test(m.name), 'Home oral diabetes medication held (metformin / sulfonylurea / SGLT2 inhibitor): acute illness, dehydration and AKI.');
